class ContentGenerationProtocolError(RuntimeError):
    """Raised when a content provider fails to return the stage JSON contract."""


def _safe_network_error_detail(reason: Any) -> str:
    """Keep useful transport diagnostics while never emitting credentials."""
    detail = re.sub(r"(?i)(authorization|api[_-]?key|token)\s*[:=]\s*[^\s,;]+", r"\1=[redacted]", str(reason or "")).strip()
    detail = re.sub(r"(?i)bearer\s+[a-z0-9._~+\-/=]+", "Bearer [redacted]", detail)
    return (detail or (type(reason).__name__ if reason is not None else "unknown transport error"))[:240]


